"""The exact single-qubit group generated by conventional H and S.

Values denote omega**phase * P[pauli] * R[rep], where omega = exp(i*pi/4),
P = (I, X, Y, Z), R = (I, H, S, HS, SH, HSH), and frame = 4*rep + pauli.
Matrix multiplication (@) applies its RIGHT operand first. Word construction
uses execution order: from_word('HS') applies H, then S, and denotes S @ H.
"""

from __future__ import annotations

from dataclasses import dataclass

from ._clifford_tables import FRAME_INVERSE, FRAME_LABELS, FRAME_PRODUCT

__all__ = ['Clif', 'I', 'X', 'Y', 'Z', 'H', 'S']


@dataclass(frozen=True, slots=True)
class Clif:
    """An exact Clifford represented by a frame and a scalar phase."""

    frame: int
    phase: int = 0

    def __post_init__(self) -> None:
        if type(self.frame) is not int or type(self.phase) is not int:
            raise TypeError('frame and phase must be integers (not booleans)')
        if not 0 <= self.frame < 24:
            raise ValueError('frame must be in range(24)')
        object.__setattr__(self, 'phase', self.phase % 8)

    @property
    def rep(self) -> int:
        """Index of the representative in (I, H, S, HS, SH, HSH)."""
        return self.frame // 4

    @property
    def pauli(self) -> int:
        """Index of the Pauli factor in (I, X, Y, Z)."""
        return self.frame % 4

    @property
    def is_identity(self) -> bool:
        """Exact identity, including its phase."""
        return self.frame == 0 and self.phase == 0

    def __repr__(self) -> str:
        """An expression that evaluates to this value."""
        # Frame labels use matrix order; from_word reads execution order.
        word = FRAME_LABELS[self.frame][::-1]
        if self.phase:
            return f'Clif.from_word({word!r}, phase={self.phase})'
        return f'Clif.from_word({word!r})'

    def __matmul__(self, other: Clif) -> Clif:
        """Matrix product: apply other, then self, retaining scalar phase."""
        if not isinstance(other, Clif):
            return NotImplemented
        frame, correction = FRAME_PRODUCT[self.frame][other.frame]
        phase = (self.phase + other.phase + correction) % 8
        return _VALUES[8 * frame + phase]

    def inverse(self) -> Clif:
        """Exact adjoint; the scalar phase changes sign."""
        frame, correction = FRAME_INVERSE[self.frame]
        phase = (correction - self.phase) % 8
        return _VALUES[8 * frame + phase]

    @classmethod
    def from_word(cls, word: str, phase: int = 0) -> Clif:
        """Reduce I/X/Y/Z/H/S in execution order, then multiply by omega**phase.

        Whitespace is ignored and the empty word denotes I. Inverses can be
        expressed with inverse(), or as words (for example 'SSS'). No
        floating-point comparison is used.
        """
        if not isinstance(word, str):
            raise TypeError('a Clifford word must be a string')
        result = I
        for letter in word:
            if letter.isspace():
                continue
            try:
                gate = _NAMED[letter]
            except KeyError:
                raise ValueError(
                    f'unknown Clifford letter {letter!r}; use IXYZHS'
                ) from None
            # Each new gate executes after the prefix, so it multiplies on the left.
            result = gate @ result
        # Clif(0, phase) is the scalar omega**phase; constructing it validates phase.
        return Clif(0, phase) @ result


# Products, inverses, and word constructors share this small pool of values.
# Direct dataclass construction remains available and uses the same equality.
_VALUES = tuple(
    Clif(frame, phase)
    for frame in range(24)
    for phase in range(8)
)
I, X, Y, Z, H, S = (_VALUES[8 * frame] for frame in (0, 1, 2, 3, 4, 8))
_NAMED = {'I': I, 'X': X, 'Y': Y, 'Z': Z, 'H': H, 'S': S}
